INSERT INTO espece (`site_id`, `nom_scientifique`, `variete`, `nom_usuel`, `role`, `strates_possibles`, `systeme`, `cycle`, `temperature_sol_semis_c`, `hauteur_m`, `largeur_m`, `delai_germination_j`, `entree_scenario`, `sortie_scenario`, `espacement_retenu_m`, `plants_par_ml`, `periode_semis`, `periode_repiquage`, `periode_recolte`, `biomasse`, `conduite_taille`, `periode_taille`, `type_plant`, `origine`, `source`, `notes`) VALUES (0, 'Tropaeolum majus', '', 'Capucine', 'couvre_sol|refuge|production|diversion|nectar', 'moyenne', 'accumulation', 'annuelle', 12, 0.3, 0.3, 12, 'placenta1', 'placenta2', 0.3, 3.33, 'mi avril', 'mi mai', 'mi juin', '++', 'libre', 'sans objet : arrachée ou couchée au sol en fin de cycle', 'direct ou godet', 'multiplication', 'fiche du porteur 2026-09-29', 'Fleurs et feuilles comestibles ; attire les pucerons loin des productions. Semis en godet sous abri mi-avril, ou direct mi-mai. Se ressème souvent seule. Hauteur en couvre-sol : les formes coureuses grimpent jusqu''à 2-3 m sur un support. Strates possibles : repère général selon le besoin en lumière (Claude, 2026-09-30), à vérifier. Système et entrée/sortie du scénario : repère général par défaut (Claude, 2026-09-30), à ajuster au film de chaque parcelle. Biomasse et taille : repère général (Claude, 2026-09-30), à caler sur la phénologie locale.') ON DUPLICATE KEY UPDATE `nom_usuel` = VALUES(`nom_usuel`), `role` = VALUES(`role`), `strates_possibles` = VALUES(`strates_possibles`), `systeme` = VALUES(`systeme`), `cycle` = VALUES(`cycle`), `temperature_sol_semis_c` = VALUES(`temperature_sol_semis_c`), `hauteur_m` = VALUES(`hauteur_m`), `largeur_m` = VALUES(`largeur_m`), `delai_germination_j` = VALUES(`delai_germination_j`), `entree_scenario` = VALUES(`entree_scenario`), `sortie_scenario` = VALUES(`sortie_scenario`), `espacement_retenu_m` = VALUES(`espacement_retenu_m`), `plants_par_ml` = VALUES(`plants_par_ml`), `periode_semis` = VALUES(`periode_semis`), `periode_repiquage` = VALUES(`period