INSERT INTO espece (`site_id`, `nom_scientifique`, `variete`, `nom_usuel`, `role`, `strates_possibles`, `systeme`, `cycle`, `hauteur_m`, `largeur_m`, `entree_scenario`, `sortie_scenario`, `espacement_retenu_m`, `plants_par_ml`, `periode_repiquage`, `periode_recolte`, `biomasse`, `rapport_cn`, `conduite_taille`, `periode_taille`, `type_plant`, `origine`, `serre_necessaire`, `orientation_bordure`, `source`, `statut_local`, `notes`) VALUES (0, 'Elaeagnus umbellata', '', 'Chalef d''automne', 'azote|biomasse|production|nectar|pollen|ombre|vent', 'haute', 'accumulation', 'ligneuse', 3.5, 1, 'placenta3', 'sec2', 0.5, 2, 'fin novembre', 'debut octobre', '+', '11', 'cepee|basitone', 'en repos végétatif, hors gel, avant le gonflement des bourgeons', 'plant ou marcotte', 'achat', 1, 'les deux', 'fiche du porteur 2026-09-29 ; ch11-construire-un-scenario-planter-un-film.md, étude de cas « Les eucalyptus »', 'ne fructifie qu''en strate émergente — ici recouvert d''ombre,', 'Fixe l''azote (actinobactéries Frankia). Ligne intérieure des bords sud et ouest, à 50 cm, à 30-40 cm du bord intérieur (Théry ch. 14). Culmine à 3-3,50 m, pousse rapide, supporte la chaleur une fois installé. Fleurs très mellifères tôt au printemps. Baies riches en antioxydants, à cueillir très mûres en septembre-octobre — ne fructifie qu''en plein soleil. Graines à stratifier 3 mois au froid. Invasif en Amérique du Nord (graines dispersées par les oiseaux) : à surveiller. Ne pas confondre avec les autres éléagnus, peu sont comestibles. C/N 11 : feuillage et litière, Illinois (Goldstein et al., 2010, J. Environ. Qual.). Système et entrée/sortie du scénario : repère général par défaut (Claude, 2026-09-30), à ajuster au film de chaque parcelle. Biomasse et taille : repère général (Claude, 2026-09-30), à caler sur la phénologie locale. Serre, bloque-herbe, bordure et déplaçable : repère (Claude, 2026-09-30, d''après le livre ch. 9 et annexes), à vérifier.') ON DUPLICATE KEY UPDATE `nom_usuel` = VALUES(`nom_usuel`), `role` = VALUES(`role`), `strates_possibles` = VALUES(`strates_possibles`), `systeme` = VALUES(`systeme`), `cycle` = VALUES(`cycle`), `hauteur_m` = VALUES(`hauteur_m`), `largeur_m` = VALUES(`largeur_m`), `entree_scenario` = VALUES(`entree_scenario`), `sortie_scenario` = VALUES(`sortie_scenario`), `espacement_retenu_m` = VALUES(`espacement_retenu_m`), `plants_par_ml` = VALUES(`plants_par_ml`), `periode_repiquage` = VALUES(`periode_repiquage`), `periode_recolte` = VALUES(`periode_recolte`), `biomasse` = VALUES(`biomasse`), `rapport_cn` = VALUES(`rapport_cn`), `conduite_taille` = VALUES(`conduite_taille`), `periode_taille` = VALUES(`periode_taille`), `type_plant` = VALUES(`type_plant`), `origine` = VALUES(`origine`), `serre_necessaire` = VALUES(`serre_necessaire`), `orientation_bordure` = VALUES(`orientation_bordure`), `source` = VALUES(`source`), `statut_local` = VALUES(`statut_local`), `notes` = VALUES(`notes`);
INSERT INTO espece (`site_id`, `nom_scientifique`, `variete`, `nom_usuel`, `role`, `strates_possibles`, `systeme`, `cycle`, `hauteur_m`, `largeur_m`, `entree_scenario`, `sortie_scenario`, `periode_repiquage`, `biomasse`, `rapport_cn`, `conduite_taille`, `periode_taille`, `type_plant`, `origine`, `source`, `statut_local`, `notes`) VALUES (0, 'Carpinus betulus', '', 'Charme', 'biomasse', 'haute|moyenne', 'accumulation', 'ligneuse', 15, 8, 'sec1', 'climax', 'fin novembre', '++', '22 à 24,5', 'trogne|cepee', 'en repos végétatif, hors gel, avant le gonflement des bourgeons', 'plant forestier racines nues', 'achat', 'connaissances/formation-joala/systemes-et-abondance.md', 'repère de conception, non vérifié', 'C/N 22 à 24,5 : litière de feuilles, Iran (Amini et al., 2011 ; Kooch et al., 2017, Catena). Hauteur et largeur : repères généraux de taille adulte libre (Claude, 2026-09-30), à vérifier. Strates possibles : repère général selon le besoin en lumière (Claude, 2026-09-30), à vérifier. Système et entrée/sortie du scénario : repère général par défaut (Claude, 2026-09-30), à ajuster au film de chaque parcelle. Biomasse et taille : repère général (Claude, 2026-09-30), à caler sur la phénologie locale. Calendrier (repère Haute-Vienne, Claude, 2026-09-30). Type de plant et origine : repère général (Claude, 2026-09-30), à vérifier.') ON DUPLICATE KEY UPDATE `nom_usuel` = VALUES(`nom_usuel`), `role` = VALUES(`role`), `strates_possibles` = VALUES(`strates_possibles`), `systeme` = VALUES(`systeme`), `cycle` = VALUES(`cycle`), `hauteur_m` = VALUES(`hauteur_m`), `largeur_m` = VALUES(`largeur_m`), `entree_scenario` = VALUES(`entree_scenario`), `sortie_scenario` = VALUES(`sortie_scenario`), `periode_repiquage` = VALUES(`periode_repiquage`), `biomasse` = VALUES(`biomasse`), `rapport_cn` = VALUES(`rapport_cn`), `conduite_taille` = VALUES(`conduite_taille`), `periode_taille` = VALUES(`periode_taille`), `type_plant` = VALUES(`type_plant`), `origine` = VALUES(`origine`), `source` = VALUES(`source`), `statut_local` = VALUES(`statut_local`), `notes` = VALUES(`notes`);
