INSERT INTO espece (`site_id`, `nom_scientifique`, `variete`, `nom_usuel`, `role`, `strates_possibles`, `systeme`, `cycle`, `hauteur_m`, `largeur_m`, `strate_service`, `entree_scenario`, `sortie_scenario`, `espacement_retenu_m`, `plants_par_ml`, `periode_repiquage`, `periode_recolte`, `biomasse`, `rapport_cn`, `conduite_taille`, `periode_taille`, `type_plant`, `origine`, `bloque_herbe`, `orientation_bordure`, `source`, `statut_local`, `notes`) VALUES (0, 'Symphytum ×uplandicum', 'Bocking 14', 'Consoude', 'biomasse|azote|mineraux|nectar|bloque_herbe', 'basse', 'accumulation', 'vivace', 1, 0.6, 'basse', 'placenta1', 'sec1', 0.6, 1.67, 'debut mars', 'mi a fin mai', '+++', '18', 'fauche', 'fauche à chaque début de floraison, plusieurs coupes par saison', 'éclat de racine', 'multiplication', 1, 'nord-est', 'fiche du porteur 2026-09-29 ; livre ch. 11 ; formation-joala/strates-et-lumiere.md', 'bordure vivante bloque-herbe ; stérile, reste en place', 'Fleurit (fleurs mauves visitées par les bourdons) mais ses graines sont stériles : ne se ressème pas, se multiplie seulement par racine. 4 à 5 coupes par an d''avril à octobre, première fin avril-mai. Racines profondes qui remontent potasse et minéraux. Indéracinable une fois installée : bien choisir l''emplacement, à bannir des bordures de planches où l''on arrache (Théry ch. 15). Le rôle « azote » renvoie à sa richesse en azote (activateur de compost), pas à une fixation. C/N 18 : masse verte à la floraison de Symphytum officinale, écotype de Moldavie, autre taxon que Bocking 14 (Țîței et al., 2025). Système et entrée/sortie du scénario : repère général par défaut (Claude, 2026-09-30), à ajuster au film de chaque parcelle. Biomasse et taille : repère général (Claude, 2026-09-30), à caler sur la phénologie locale. Serre, bloque-herbe, bordure et déplaçable : repère (Claude, 2026-09-30, d''après le livre ch. 9 et annexes), à vérifier.') ON DUPLICATE KEY UPDATE `nom_usuel` = VALUES(`nom_usuel`), `role` = VALUES(`role`), `strates_possibles` = VALUES(`strates_possibles`), `systeme` = VALUES(`systeme`), `cycle` = VALUES(`cycle`), `hauteur_m` = VALUES(`hauteur_m`), `largeur_m` = VALUES(`largeur_m`), `strate_service` = VALUES(`strate_service`), `entree_scenario` = VALUES(`entree_scenario`), `sortie_scenario` = VALUES(`sortie_scenario`), `espacement_retenu_m` = VALUES(`espacement_retenu_m`), `plants_par_ml` = VALUES(`plants_par_ml`), `periode_repiquage` = VALUES(`periode_repiquage`), `periode_recolte` = VALUES(`periode_recolte`), `biomasse` = VALUES(`biomasse`), `rapport_cn` = VALUES(`rapport_cn`), `conduite_taille` = VALUES(`conduite_taille`), `periode_taille` = VALUES(`periode_taille`), `type_plant` = VALUES(`type_plant`), `origine` = VALUES(`origine`), `bloque_herbe` = VALUES(`bloque_herbe`), `orientation_bordure` = VALUES(`orientation_bordure`), `source` = VALUES(`source`), `statut_local` = VALUES(`statut_local`), `notes` = VALUES(`notes`);
