INSERT INTO espece (`site_id`, `nom_scientifique`, `variete`, `nom_usuel`, `role`, `strates_possibles`, `systeme`, `cycle`, `temperature_sol_semis_c`, `hauteur_m`, `largeur_m`, `strate_production`, `delai_germination_j`, `entree_scenario`, `sortie_scenario`, `periode_semis`, `periode_recolte`, `biomasse`, `conduite_taille`, `periode_taille`, `type_plant`, `origine`, `source`, `statut_local`, `notes`) VALUES (0, 'Vicia faba', '', 'Fève', 'production|azote', 'emergente|haute', 'accumulation', 'annuelle', 5, 1, 0.3, 'emergente', 10, 'placenta1', 'placenta1', 'fin fevrier', 'mi juin', '++', 'fauche', 'coupée ou couchée au sol dès la fin de floraison', 'direct', 'multiplication', 'connaissances/formation-joala/strates-et-lumiere.md; ch11-construire-un-scenario-planter-un-film.md', 'émergente au moment de l''année selon strates-et-lumiere.md ;', 'Hauteur et largeur : repères généraux de taille adulte libre (Claude, 2026-09-30), à vérifier. Système et entrée/sortie du scénario : repère général par défaut (Claude, 2026-09-30), à ajuster au film de chaque parcelle. Biomasse et taille : repère général (Claude, 2026-09-30), à caler sur la phénologie locale. Calendrier (repère Haute-Vienne, Claude, 2026-09-30) : semis d''automne possible en sol drainé si l''hiver est doux ; récolte en juin. Germination (repère, Claude, 2026-09-30). Type de plant et origine : repère général (Claude, 2026-09-30), à vérifier.') ON DUPLICATE KEY UPDATE `nom_usuel` = VALUES(`nom_usuel`), `role` = VALUES(`role`), `strates_possibles` = VALUES(`strates_possibles`), `systeme` = VALUES(`systeme`), `cycle` = VALUES(`cycle`), `temperature_sol_semis_c` = VALUES(`temperature_sol_semis_c`), `hauteur_m` = VALUES(`hauteur_m`), `largeur_m` = VALUES(`largeur_m`), `strate_production` = VALUES(`strate_production`), `delai_germination_j` = VALUES(`delai_germination_j`), `entree_scenario` = VALUES(`entree_scenario`), `sortie_scenario` = VALUES(`sortie_scenario`), `periode_semis` = VALUES(`periode_semis`), `periode_re