INSERT INTO espece (`site_id`, `nom_scientifique`, `variete`, `nom_usuel`, `role`, `strates_possibles`, `systeme`, `cycle`, `hauteur_m`, `largeur_m`, `strate_service`, `entree_scenario`, `sortie_scenario`, `periode_repiquage`, `biomasse`, `conduite_taille`, `periode_taille`, `type_plant`, `origine`, `source`, `statut_local`, `notes`) VALUES (0, 'Wisteria', '', 'Glycine', 'ombre|biomasse|nectar', 'emergente|7_liane', 'accumulation', 'ligneuse', 10, 4, 'emergente', 'placenta3', 'sec3', 'fin novembre', '+++', 'libre', 'en vert en été, puis taille courte en repos végétatif hors gel', 'plant greffé en conteneur', 'achat', 'livre-bienvenue-en-syntropie ch. 15 § 9.3, p. 131', 'toxique pour l''homme et l''animal', 'Vive et rapide ; ne craint pas la taille de perturbation, vite nécessaire ; rameaux bien proportionnés en azote et en carbone ; ralentit l''impact des averses de grêle ; précieuse pour les pollinisateurs. Toxique à la consommation humaine et animale. Hauteur et largeur : repères généraux de taille adulte libre (Claude, 2026-09-30), à vérifier. Système et entrée/sortie du scénario : repère général par défaut (Claude, 2026-09-30), à ajuster au film de chaque parcelle. Biomasse et taille : repère général (Claude, 2026-09-30), à caler sur la phénologie locale. Calendrier (repère Haute-Vienne, Claude, 2026-09-30). Type de plant et origine : repère général (Claude, 2026-09-30), à vérifier.') ON DUPLICATE KEY UPDATE `nom_usuel` = VALUES(`nom_usuel`), `role` = VALUES(`role`), `strates_possibles` = VALUES(`strates_possibles`), `systeme` = VALUES(`systeme`), `cycle` = VALUES(`cycle`), `hauteur_m` = VALUES(`hauteur_m`), `largeur_m` = VALUES(`largeur_m`), `strate_service` = VALUES(`strate_service`), `entree_scenario` = VALUES(`entree_scenario`), `sortie_scenario` = VALUES(`sortie_scenario`), `periode_repiquage` = VALUES(`periode_repiquage`), `biomasse` = VALUES(`biomasse`), `conduite_taille` = VALUES(`conduite_taille`), `periode_taille` = VALUES(`periode_taille`), `type_plant` = VALUES(`type_plant`), `origine` = VALUES(`origine`), `source` = VALUES(`source`), `statut_local` = VALUES(`statut_local`), `notes` = VALUES(`notes`);
INSERT INTO espece (`site_id`, `nom_scientifique`, `variete`, `nom_usuel`, `role`, `strates_possibles`, `systeme`, `cycle`, `temperature_sol_semis_c`, `hauteur_m`, `largeur_m`, `delai_germination_j`, `entree_scenario`, `sortie_scenario`, `espacement_retenu_m`, `plants_par_ml`, `periode_semis`, `periode_repiquage`, `periode_recolte`, `biomasse`, `conduite_taille`, `periode_taille`, `type_plant`, `origine`, `orientation_bordure`, `source`, `statut_local`, `notes`) VALUES (0, 'Lycium barbarum', '', 'Goji', 'production|biomasse|perturbation|racines|nectar|pollen', 'moyenne', 'accumulation', 'ligneuse', 15, 2.5, 1, 10, 'placenta3', 'sec2', 0.5, 2, 'mi mars', 'mi mai', 'debut aout', '+++', 'tresse|basitone', 'en repos végétatif, hors gel, avant le gonflement des bourgeons', 'bouture, drageon ou godet', 'multiplication', 'les deux', 'ch11-construire-un-scenario-planter-un-film.md; connaissances/formation-joala/calendrier-et-taille-hivernale.md; tortues', 'support de perturbation majeur — résistant au gel et aux lim', 'Ligne intérieure des bords sud et ouest à 50 cm, ou conduit en tressage à 20 cm sur les bords nord et est (Théry ch. 14). Épitone : conduit « tressé », on taille et pose au sol les deux tiers de la plante chaque saison — grosse biomasse équilibrée. Racines plongeantes qui remontent eau et nutriments. Résiste au gel et aux limaces. Drageonne. Récolte d''août à octobre. Semis facile à 20 °C sous abri, repiqué mi-mai, bouture ou plant se mettent en place de novembre à mars. Système et entrée/sortie du scénario : repère général par défaut (Claude, 2026-09-30), à ajuster au film de chaque parcelle. Biomasse et taille : repère général (Claude, 2026-09-30), à caler sur la phénologie locale. Serre, bloque-herbe, bordure et déplaçable : repère (Claude, 2026-09-30, d''après le livre ch. 9 et annexes), à vérifier.') ON DUPLICATE KEY UPDATE `nom_usuel` = VALUES(`nom_usuel`), `role` = VALUES(`role`), `strates_possibles` = VALUES(`strates_possibles`), `systeme` = VALUES(`systeme`), `cycle` = VALUES(`cycle`), `temperature_sol_semis_c` = VALUES(`temperature_sol_semis_c`), `hauteur_m` = VALUES(`hauteur_m`), `largeur_m` = VALUES(`largeur_m`), `delai_germination_j` = VALUES(`delai_germination_j`), `entree_scenario` = VALUES(`entree_scenario`), `sortie_scenario` = VALUES(`sortie_scenario`), `espacement_retenu_m` = VALUES(`espacement_retenu_m`), `plants_par_ml` = VALUES(`plants_par_ml`), `periode_semis` = VALUES(`periode_semis`), `periode_repiquage` = VALUES(`periode_repiquage`), `periode_recolte` = VALUES(`periode_recolte`), `biomasse` = VALUES(`biomasse`), `conduite_taille` = VALUES(`conduite_taille`), `periode_taille` = VALUES(`periode_taille`), `type_plant` = VALUES(`type_plant`), `origine` = VALUES(`origine`), `orientation_bordure` = VALUES(`orientation_bordure`), `source` = VALUES(`source`), `statut_local` = VALUES(`statut_local`), `notes` = VALUES(`notes`);
