, `type_plant` = VALUES(`type_plant`), `origine` = VALUES(`origine`), `orientation_bordure` = VALUES(`orientation_bordure`), `deplacable` = VALUES(`deplacable`), `source` = VALUES(`source`), `statut_local` = VALUES(`statut_local`), `notes` = VALUES(`notes`);
INSERT INTO espece (`site_id`, `nom_scientifique`, `variete`, `nom_usuel`, `role`, `strates_possibles`, `systeme`, `cycle`, `temperature_sol_semis_c`, `hauteur_m`, `largeur_m`, `strate_production`, `delai_germination_j`, `entree_scenario`, `sortie_scenario`, `espacement_retenu_m`, `plants_par_ml`, `periode_semis`, `periode_recolte`, `biomasse`, `conduite_taille`, `periode_taille`, `type_plant`, `origine`, `source`, `statut_local`, `notes`) VALUES (0, 'Phaseolus vulgaris', 'nain', 'Haricot nain', 'production|azote', 'moyenne', 'accumulation', 'annuelle', 10, 0.4, 0.3, 'moyenne', 8, 'placenta1', 'placenta1', 0.08, 12.5, 'mi mai', 'fin juillet', '+', 'libre', 'sans objet : arrachée ou couchée au sol en fin de cycle', 'direct', 'achat', 'fiche du porteur 2026-09-29 ; formation-joala/strates-et-lumiere.md', 'à l''ombre du maïs — exemple Dordogne, sud', 'À semer un mois après un tuteur vivant si en association. Levée fiable au-dessus de 12 °C, risque de pourriture en sol froid. Récolte 60-70 jours après semis. Système et entrée/sortie du scénario : repère général par défaut (Claude, 2026-09-30), à ajuster au film de chaque parcelle. Biomasse et taille : repère général (Claude, 2026-09-30), à caler sur la phénologie locale.') ON DUPLICATE KEY UPDATE `nom_usuel` = VALUES(`nom_usuel`), `role` = VALUES(`role`), `strates_possibles` = VALUES(`strates_possibles`), `systeme` = VALUES(`systeme`), `cycle` = VALUES(`cycle`), `temperature_sol_semis_c` = VALUES(`temperature_sol_semis_c`), `hauteur_m` = VALUES(`hauteur_m`), `largeur_m` = VALUES(`largeur_m`), `strate_production` = VALUES(`strate_production`), `delai_germination_j` = VALUES(`delai_germination_j`), `entree_scenario` = VALUES(`entree_scenario`), `sortie_scenario` = VALUES(`sortie_scenario`), `espacement_retenu_m` = VALUES(`espacement_retenu_m`), `plants_par_ml` = VALUES(`plants_par_ml`), `periode_semis` = VALUES(`periode_semis`), `periode_recolte` = VALUES(`periode_recolte`), `biomasse` = VALUES(`biomasse`), `conduite_taille` = VALUES(`conduite_taille`), `periode_taille` = VALUES(`periode_taille`), `type_plant` = VALUES(`type_plant`), `origine` = VALUES(`origine`), `source` = VALUES(`source`), `statut_local` = VALUES(`statut_local`), `notes` = VALUES(`notes`);
INSERT INTO espece (`site_id`, `nom_scientifique`, `variete`, `nom_usuel`, `role`, `strates_possibles`, `systeme`, `cycle`, `temperature_sol_semis_c`, `hauteur_m`, `largeur_m`, `delai_germination_j`, `entree_scenario`, `sortie_scenario`, `espacement_retenu_m`, `plants_par_ml`, `periode_semis`, `periode_repiquage`, `periode_recolte`, `biomasse`, `conduite_taille`, `periode_taille`, `type_plant`, `origine`, `serre_necessaire`, `bloque_herbe`, `orientation_bordure`, `deplacable`, `source`, `statut_local`, `notes`) VALUES (0, 'Hyssopus officinalis', '', 'Hysope', 'nectar|pollen|refuge|production|bloque_herbe', 'emergente', 'colonisation', 'ligneuse', 12, 0.5, 1, 14, 'placenta2', 'sec1', 0.4, 2.5, 'debut avril', 'mi mai', 'debut juillet', '+', 'eventail', 'à la reprise de printemps après les gelées, puis légèrement après floraison', 'godet sous abri, ou bouture', 'mixte', 1, 1, 'sud-ouest', 1, 'fiche du porteur 2026-09-29 ; livre-bienvenue-en-syntropie ch. 03 § 4 ; ch. 14 § 4.2, plan p. 117', 'bande extérieure, face sud ou ouest — espacement indicatif ;', 'Sous-arbrisseau 40-60 cm, plein soleil, sol sec et drainé. Bande extérieure des bords sud et ouest (Théry ch. 14). Très mellifère de juillet à septembre. Germination lente (10 à 30 jours). Rabattre au printemps. Strates possibles : repère général selon le besoin en lumière (Claude, 2026-09-30), à vérifier. Système et entrée/sortie du scénario : repère général par défaut (Claude, 2026-09-30), à ajuster au film de chaque parcelle. Biomasse et taille : repère général (Claude, 2026-09-30), à caler sur la phénologie locale. Serre, bloque-herbe, bordure et déplaçable : repère (Claude, 2026-09-30, d''après le livre ch. 9 et annexes), à vérifier.') ON DUPLICATE KEY UPDATE `nom_usuel` = VALUES(`nom_usuel`), `role` = VALUES(`role`), `strates_possibles` = VALUES(`strates_possibles`), `systeme` = VALUES(`systeme`), `cycle` = VALUES(`cycle`), `temperature_sol_semis_c` = VALUES(`temperature_sol_semis_c`), `hauteur_m` = VALUES(`hauteur_m`), `largeur_m` = VALUES(`largeur_m`), `delai_germination_j` = VALUES(`delai_germination_j`), `entree_scenario` = VALUES(`entree_scenario`), `sortie_scenario` = VALUES(`sortie_scenario`), `espacement_retenu_m` = VALUES(`espacement_retenu_m`), `plants_par_ml` = VALUES(`plants_par_ml`), `periode_semis` = VALUES(`periode_semis`), `periode_repiquage` = VALUES(`periode_repiquage`), `periode_recolte` = VALUES(`periode_recolte`), `biomasse` = VALUES(`biomasse`), `conduite_taille` = VALUES(`conduite_taille`), `periode_taille` = VALUES(`periode_taille`), `type_plant` = VALUES(`type_plant`), `origine` = VALUES(`origine`), `serre_necessaire` = VALUES(`serre_necessaire`), `bloque_herbe` = VALUES(`bloque_herbe`), `orientation_bordure` = VALUES(`orientation_bordure`), `deplacable` = VALUES(`deplacable`), `source` = VALUES(`source`), `statut_local` = VALUES(`statut_local`), `notes` = VALUES(`notes`);
INSERT INTO espece (`site_id`, `nom_scientifique`, `variete`, `nom_usuel`, `role`, `strates_possibles`, `systeme`, `cycle`, `temperature_sol_semis_c`, `hauteur_m`, `largeur_m`, `strate_service`, `delai_germination_j`, `entree_scenario`, `sortie_scenario`, `periode_semis`, `periode_repiquage`, `periode_recolte`, `biomasse`, `conduite_taille`, `periode_taille`, `type_plant`, `origine`, `source`, `statut_local`, `notes`) VALUES (0, 'Cucumis metuliferus', '', 'Kiwano', 'ombre', 'emergente|7_liane', 'accumulation', 'annuelle', 15, 3, 1, 'emergente', 10, 'placenta1', 'placenta2', 'mi avril', 'fin mai', 'debut septembre', '++', 'libre', 'sans objet : arrachée ou couchée au sol en fin de cycle', 'godet, sous abri chaud', 'achat', 'livre-bienvenue-en-syntropie ch. 15 § 9.4, p. 131', 'la première année seulement', 'Liane annuelle résistante à la chaleur : double les lianes pérennes la première année, le temps qu''elles s''installent. Hauteur et largeur : repères généraux de taille adulte libre (Claude, 2026-09-30), à vérifier. Système et entrée/sortie du scénario : repère général par défaut (Claude, 2026-09-30), à ajuster au film de chaque parcelle. Biomasse et taille : repère général (Claude, 2026-09-30), à caler sur la phénologie locale. Calendrier (repère Haute-Vienne, Claude, 2026-09-30). Germination (repère, Claude, 2026-09-30). Type de plant et origine : repère général (Claude, 2026-09-30), à vérifier.') ON DUPLICATE KEY UPDATE `nom_usuel` = VALUES(`nom_usuel`), `role` = VALUES(`role`), `strates_possibles` = VALUES(`strates_possibles`), `systeme` = VALUES(`systeme`), `cycle` = VALUES(`cycle`), `temperature_sol_semis_c` = VALUES(`temperature_sol_semis_c`), `hauteur_m` = VALUES(`hauteur_m`), `largeur_m` = VALUES(`largeur_m`), `strate_service` = VALUES(`strate_service`), `delai_germination_j` = VALUES(`delai_germination_j`), `entree_scenario` = VALUES(`entree_scenario`), `sortie_scenario` = VALUES(`sortie_scenario`), `periode_semis` = VALUES(`periode_semis`), `periode_repiquage` = VALUES(`periode_repiquage`), `periode_recolte` = VALUES(`periode_recolte`), `biomasse` = VALUES(`biomasse`), `conduite_taille` = VALUES(`conduite_taille`), `periode_taille` = VALUES(`periode_taille`), `type_plant` = VALUES(`type_plant`), `origine` = VALUES(`origine`), `source` = VALUES(`source`), `statut_local` = VALUES(`statut_local`), `notes` = VALUES(`notes`);
INSERT INTO espece (`site_id`, `nom_scientifique`, `variete`, `nom_usuel`, `role`, `strates_possibles`, `systeme`, `cycle`, `hauteur_m`, `largeur_m`, `strate_production`, `entree_scenario`, `sortie_scenario`, `periode_repiquage`, `periode_recolte`, `biomasse`, `conduite_taille`, `periode_taille`, `type_plant`, `origine`, `source`, `statut_local`, `notes`) VALUES (0, 'Actinidia arguta', '', 'Kiwaï', 'production', 'haute|7_liane', 'abondance', 'ligneuse', 8, 3, 'haute', 'sec1', 'sec3', 'mi avril', 'mi septembre', '++', 'libre', 'en repos végétatif, hors gel, avant le gonflement des bourgeons', 'plant en conteneur', 'achat', 'livre-bienvenue-en-syntropie ch. 15 § 9.3 bis, p. 131', 'selon l''eau disponible ; face nord-est', 'Strate haute, à l''ombre des lianes émergentes, selon les apports en eau ; orienté face nord-est. Hauteur et largeur : repères généraux de taille adulte libre (Claude, 2026-09-30), à vérifier. Système et entrée/sortie du scénario : repère général par défaut (Claude, 2026-09-30), à ajuster au film de chaque parcelle. Biomasse et taille : repère général (Claude, 2026-09-30), à caler sur la phénologie locale. Calendrier (repère Haute-Vienne, Claude, 2026-09-30) : plantation au printemps (jeunes pousses gélives) ; récolte septembre-octobre. Type de plant et origine : repère général (Claude, 2026-09-30), à vérifier.') ON DUPLICATE KEY UPDATE `nom_usuel` = VALUES(`nom_usuel`), `role` = VALUES(`role`), `strates_possibles` = VALUES(`strates_possibles`), `systeme` = VALUES(`systeme`), `cycle` = VALUES(`cycle`), `hauteur_m` = VALUES(`hauteur_m`), `largeur_m` = VALUES(`largeur_m`), `strate_production` = VALUES(`strate_production`), `entree_scenario` = VALUES(`entree_scenario`), `sortie_scenario` = VALUES(`sortie_scenario`), `periode_repiquage` = VALUES(`periode_repiquage`), `periode_recolte` = VALUES(`periode_recolte`), `biomasse` = VALUES(`biomasse`), `conduite_taille` = VALUES(`conduite_taille`), `periode_taille` = VALUES(`periode_taille`), `type_plant` = VA