INSERT INTO espece (`site_id`, `nom_scientifique`, `variete`, `nom_usuel`, `role`, `strates_possibles`, `systeme`, `cycle`, `hauteur_m`, `largeur_m`, `strate_production`, `entree_scenario`, `sortie_scenario`, `periode_repiquage`, `periode_recolte`, `biomasse`, `conduite_taille`, `periode_taille`, `type_plant`, `origine`, `source`, `statut_local`, `notes`) VALUES (0, 'Actinidia deliciosa', '', 'Kiwi', 'production', 'haute|7_liane', 'abondance', 'ligneuse', 8, 4, 'haute', 'sec1', 'sec3', 'mi avril', 'debut novembre', '++', 'libre', 'en repos végétatif, hors gel, avant le gonflement des bourgeons', 'plant en conteneur, mâle et femelle', 'achat', 'livre-bienvenue-en-syntropie ch. 15 § 9.1 et 9.3 bis, p. 131-132', 'à l''est ou au nord, ou entre les poteaux centraux', 'Strate haute, à l''ombre des lianes émergentes ; cueillette facilitée par la structure. À l''est ou au nord, ou planté au cœur de la tortue entre les poteaux centraux. Hauteur et largeur : repères généraux de taille adulte libre (Claude, 2026-09-30), à vérifier. Système et entrée/sortie du scénario : repère général par défaut (Claude, 2026-09-30), à ajuster au film de chaque parcelle. Biomasse et taille : repère général (Claude, 2026-09-30), à caler sur la phénologie locale. Calendrier (repère Haute-Vienne, Claude, 2026-09-30) : cueillette avant les gelées, mûrissement au fruitier. Type de plant et origine : repère général (Claude, 2026-09-30), à vérifier.') ON DUPLICATE KEY UPDATE `nom_usuel` = VALUES(`nom_usuel`), `role` = VALUES(`role`), `strates_possibles` = VALUES(`strates_possibles`), `systeme` = VALUES(`systeme`), `cycle` = VALUES(`cycle`), `hauteur_m` = VALUES(`hauteur_m`), `largeur_m` = VALUES(`largeur_m`), `strate_production` = VALUES(`strate_production`), `entree_scenario` = VALUES(`entree_scenario`), `sortie_scenario` = VALUES(`sortie_scenario`), `periode_repiquage` = VALUES(`periode_repiquage`), `periode_recolte` = VALUES(`periode_recolte`), `biomasse` = VALUES(`biomasse`), `conduite_taille` = VALUES(`conduite_taille`), `periode_taille` = VALUES(`periode_taille`), `type_plant` = VALUES(`type_plant`), `origine` = VALUES(`origine`), `source` = VALUES(`source`), `statut_local` = VALUES(`statut_local`), `notes` = VALUES(`notes`);
INSERT INTO espece (`site_id`, `nom_scientifique`, `variete`, `nom_usuel`, `role`, `strates_possibles`, `systeme`, `cycle`, `temperature_sol_semis_c`, `hauteur_m`, `largeur_m`, `strate_production`, `strate_service`, `delai_germination_j`, `entree_scenario`, `sortie_scenario`, `espacement_retenu_m`, `plants_par_ml`, `periode_semis`, `periode_repiquage`, `periode_recolte`, `biomasse`, `conduite_taille`, `periode_taille`, `type_plant`, `origine`, `serre_necessaire`, `bloque_herbe`, `orientation_bordure`, `deplacable`, `source`, `statut_local`, `notes`) VALUES (0, 'Lavandula angustifolia', '', 'Lavande', 'nectar|pollen|refuge|production|bloque_herbe', 'emergente', 'colonisation', 'ligneuse', 15, 0.6, 1, 'emergente', 'emergente', 21, 'placenta2', 'sec1', 0.5, 2, 'mi mars', 'mi mai', 'debut juillet', '+', 'eventail', 'après floraison, sans couper dans le vieux bois', 'godet sous abri, ou bouture', 'mixte', 1, 1, 'sud-ouest', 1, 'fiche du porteur 2026-09-29 ; formation-joala/strates-et-lumiere.md ; livre ch. 03, ch. 14', 'exemple Dordogne, sud — non transposable tel quel', 'Stratifier les graines 3-4 semaines au froid avant semis. Sol drainé, plein soleil. Bande extérieure des bords sud et ouest (Théry ch. 14). Tailler après floraison sans couper le vieux bois. Vit 8-10 ans. Système et entrée/sortie du scénario : repère général par défaut (Claude, 2026-09-30), à ajuster au film de chaque parcelle. Biomasse et taille : repère général (Claude, 2026-09-30), à caler sur la phénologie locale. Serre, bloque-herbe, bordure et déplaçable : repère (Claude, 2026-09-30, d''après le livre ch. 9 et annexes), à vérifier.') ON DUPLICATE KEY UPDATE `nom_usuel` = VALUES(`nom_usuel`), `role` = VALUES(`role`), `strates_possibles` = VALUES(`strates_possibles`), `systeme` = VALUES(`systeme`), `cycle` = VALUES(`cycle`), `temperature_sol_semis_c` = VALUES(`temperature_sol_semis_c`), `hauteur_m` = VALUES(`hauteur_m`), `largeur_m` = VALUES(`largeur_m`), `strate_production` = VALUES(`strate_production`), `strate_service` = VALUES(`strate_service`), `delai_germination_j` = VALUES(`delai_germination_j`), `entree_scenario` = VALUES(`entree_scenario`), `sortie_scenario` = VALUES(`sortie_scenario`), `espacement_retenu_m` = VALUES(`espacement_retenu_m`), `plants_par_ml` = VALUES(`plants_par_ml`), `periode_semis` = VALUES(`periode_semis`), `periode_repiquage` = VALUES(`periode_repiquage`), `periode_recolte` = VALUES(`periode_recolte`), `biomasse` = VALUES(`biomasse`), `conduite_taille` = VALUES(`conduite_taille`), `periode_taille` = VALUES(`periode_taille`), `type_plant` = VALUES(`type_plant`), `origine` = VALUES(`origine`), `serre_necessaire` = VALUES(`serre_necessaire`), `bloque_herbe` = VALUES(`bloque_herbe`), `orientation_bordure` = VALUES(`orientation_bordure`), `deplacable` = VALUES(`deplacable`), `source` = VALUES(`source`), `statut_local` = VALUES(`statut_local`), `notes` = VALUES(`notes`);
INSERT INTO espece (`site_id`, `nom_scientifique`, `variete`, `nom_usuel`, `role`, `strates_possibles`, `systeme`, `cycle`, `hauteur_m`, `largeur_m`, `entree_scenario`, `sortie_scenario`, `espacement_retenu_m`, `plants_par_ml`, `periode_repiquage`, `periode_recolte`, `biomasse`, `conduite_taille`, `periode_taille`, `type_plant`, `origine`, `serre_necessaire`, `bloque_herbe`, `orientation_bordure`, `deplacable`, `source`, `statut_local`, `notes`) VALUES (0, 'Lavandula ×intermedia', '', 'Lavandin', 'nectar|pollen|refuge|production|bloque_herbe', 'emergente', 'colonisation', 'ligneuse', 0.9, 1, 'placenta2', 'sec1', 0.8, 1.25, 'mi avril', 'fin juillet', '+', 'eventail', 'après floraison, sans couper dans le vieux bois', 'bouture', 'multiplication', 1, 1, 'sud-ouest', 1, 'fiche du porteur 2026-09-29 ; livre-bienvenue-en-syntropie ch. 14 § 4.2, plan p. 117', 'bande extérieure, face sud ou ouest — espacement indicatif ;', 'Hybride stérile : ne se sème pas, bouture semi-aoûtée en août-septembre. Plus grand et plus productif que la lavande. Bande extérieure des bords sud et ouest (Théry ch. 14, qui l''espace à 40 cm). Plantation au printemps ou à l''automne. Strates possibles : repère général selon le besoin en lumière (Claude, 2026-09-30), à vérifier. Système et entrée/sortie du scénario : repère général par défaut (Claude, 2026-09-30), à ajuster au film de chaque parcelle. Biomasse et taille : repère général (Claude, 2026-09-30), à caler sur la phénologie locale. Serre, bloque-herbe, bordure et déplaçable : repère (Claude, 2026-09-30, d''après le livre ch. 9 et annexes), à vérifier.') ON DUPLICATE KEY UPDATE `nom_usuel` = VALUES(`nom_usuel`), `role` = VALUES(`role`), `strates_possibles` = VALUES(`strates_possibles`), `systeme` = VALUES(`systeme`), `cycle` = VALUES(`cycle`), `hauteur_m` = VALUES(`hauteur_m`), `largeur_m` = VALUES(`largeur_m`), `entree_scenario` = VALUES(`entree_scenario`), `sortie_scenario` = VALUES(`sortie_scenario`), `espacement_retenu_m` = VALUES(`espacement_retenu_m`), `plants_par_ml` = VALUES(`plants_par_ml`), `periode_repiquage` = VALUES(`periode_repiquage`), `periode_recolte` = VALUES(`periode_recolte`), `biomasse` = VALUES(`biomasse`), `conduite_taille` = VALUES(`conduite_taille`), `periode_taille` = VALUES(`periode_taille`), `type_plant` = VALUES(`type_plant`), `origine` = VALUES(`origine`), `serre_necessaire` = VALUES(`serre_necessaire`), `bloque_herbe` = VALUES(`bloque_herbe`), `orientation_bordure` = VALUES(`orientation_bordure`), `deplacable` = VALUES(`deplacable`), `source` = VALUES(`source`), `statut_local` = VALUES(`statut_local`), `notes` = VALUES(`notes`);
INSERT INTO espece (`site_id`, `nom_scientifique`, `variete`, `nom_usuel`, `role`, `strates_possibles`, `systeme`, `cycle`, `hauteur_m`, `largeur_m`, `entree_scenario`, `sortie_scenario`, `periode_repiquage`, `biomasse`, `conduite_taille`, `periode_taille`, `type_plant`, `origine`, `orientation_bordure`, `deplacable`, `source`, `statut_local`, `notes`) VALUES (0, 'Lonicera fragrantissima', '', 'Lonicera fragrantissima', 'biomasse', 'moyenne', 'accumulation', 'ligneuse', 2.5, 3, 'placenta3', 'sec2', 'fin novembre', '+++', 'basitone', 'avant sa floraison d''hiver, sans attendre la fin des frimas', 'bouture, en tipi', 'multiplication', 'les deux', 1, 'ch11-construire-un-scenario-planter-un-film.md, étude de cas « Les eucalyptus »', 'boutures en tipi', 'Hauteur et largeur : repères généraux de taille adulte libre (Claude, 2026-09-30), à vérifier. Système et entrée/sortie du scénario : repère général par défaut (Claude, 2026-09-30), à ajuster au film de chaque parcelle. Biomasse et taille : repère général (Claude, 2026-09-30), à caler sur la phénologie locale. Calendrier (repère Haute-Vienne, Claude, 2026-09-30). Type de plant et origine : repère général (Claude, 2026-09-30), à vérifier. Serre, bloque-herbe, bordure et déplaçable : repère (Claude, 2026-09-30, d''après le livre ch. 9 et annexes), à vérifier.') ON DUPLICATE KEY UPDATE `nom_usuel` = VALUES(`nom_usuel`), `role` = VALUES(`role`), `strates_possibles` = VALUES(`strates_possibles`), `systeme` = VALUES(`systeme`), `cycle` = VALUES(`cycle`), `hauteur_m` = VALUES(`hauteur_m`), `largeur_m` = VALUES(`largeur_m`), `entree_scenario` = VALUES(`entree_scenario`), `sortie_scenario` = VALUES(`sortie_scenario`), `periode_repiquage` = VALUES(`periode_repiquage`), `biomasse` = VALUES(`biomasse`), `conduite_taille` = VALUES(`conduite_taille`), `periode_taille` = VALUES(`periode_taille`), `type_plant` = VALUES(`type_plant`), `origine` = VALUES(`origine`), `orientation_bordure` = VALUES(`orientation_bordure`), `deplacable` = VALUES(`deplacable`), `source` = VALUES(`source`), `statut_local` = VALUES(`statut_local`), `notes` = VALUES(`notes`);
INSERT INTO espece (`site_id`, `nom_scientifique`, `variete`, `nom_usuel`, `role`, `strates_possibles`, `systeme`, `cycle`, `temperature_sol_semis_c`, `hauteur_m`, `largeur_m`, `strate_production`, `strate_service`, `delai_germination_j`, `entree_scenario`, `sortie_scenario`, `espacement_retenu_m`, `plants_par_ml`, `periode_semis`, `periode_repiquage`, `periode_recolte`, `biomasse`, `conduite_taille`, `periode_taille`, `type_plant`, `origine`, `source`, `statut_local`, `notes`) VALUES (0, 'Zea mays', 'population locale', 'Maïs population', 'biomasse|tuteur', 'emergente|haute', 'accumulation', 'annuelle', 6, 3, 0.25, 'emergente', 'haute', 10, 'placenta1', 'placenta2', 0.1, 4, 'fin avril', 'mi mai', 'fin septembre', '+++', 'fauche', 'coupée ou couchée au sol dès la fin de floraison', 'direct, en poquets', 'multiplication', 'fiche du porteur 2026-09-29 ; formation-joala/strates-et-lumiere.md ; livre ch. 11', 'divergence entre sources : émergente ou haute', 'Tranchée centrale de planche, à tailler pour la biomasse. 6 °C = zéro de germination : levée en ~6 semaines à 6 °C, ~1 semaine à 10 °C — attendre un sol stable au-dessus de 10 °C. Système et entrée/sortie du scénario : repère général par défaut (Claude, 2026-09-30), à ajuster au film de chaque parcelle. Biomasse et taille : repère général (Claude, 2026-09-30), à caler sur la phénologie locale.') ON DUPLICATE KEY UPDATE `nom_usuel` = VALUES(`nom_usuel`), `role` = VALUES(`role`), `strates_possibles` = VALUES(`strates_possibles`), `systeme` = VALUES(`systeme`), `cycle` = VALUES(`cycle`), `temperature_sol_semis_c` = VALUES(`temperature_sol_semis_c`), `hauteur_m` = VALUES(`hauteur_m`), `largeur_m` = VALUES(`largeur_m`), `strate_production` = VALUES(`strate_production`), `strate_service` = VALUES(`strate_service`), `delai_germination_j` = VALUES(`delai_germination_j`), `entree_scenario` = VALUES(`entree_scenario`), `sortie_scenario` = VALUES(`sortie_scenario`), `espacement_retenu_m` = VALUES(`espacement_retenu_m`), `plants_par_ml` = VALUES(`plants_par_ml`), `periode_semis` = VALUES(`periode_semis`), `periode_repiquage` = VALUES(`periode_repiquage`), `periode_recolte` = VALUES(`periode_recolte`), `biomasse` = VALUES(`biomasse`), `conduite_taille` = VALUES(`conduite_taille`), `periode_taille` = VALUES(`periode_taille`), `type_plant` = VALUES(`type_plant`), `origine` = VALUES(`origine`), `source` = VALUES(`source`), `statut_local` = VALUES(`statut_local`), `notes` = VALUES(`notes`);
INSERT INTO espece (`site_id`, `nom_scientifique`, `variete`, `nom_usuel`, `role`, `strates_possibles`, `systeme`, `cycle`, `hauteur_m`, `largeur_m`, `strate_production`, `strate_service`, `entree_scenario`, `sortie_scenario`, `espacement_retenu_m`, `plants_par_ml`, `periode_repiquage`, `periode_recolte`, `biomasse`, `conduite_taille`, `periode_taille`, `type_plant`, `origine`, `bloque_herbe`, `orientation_bordure`, `source`, `statut_local`, `notes`) VALUES (0, 'Mentha suaveolens', '', 'Menthe à feuilles rondes', 'bloque_herbe|couvre_sol|biomasse|production|nectar|pollen|refuge', 'basse', 'accumulation', 'vivace', 0.6, 0.5, 'basse', 'basse', 'placenta1', 'sec1', 0.5, 2, 'debut avril', 'debut juin', '++', 'fauche', 'fauche à chaque début de floraison, plusieurs coupes par saison', 'éclat de touffe ou stolon', 'multiplication', 1, 'nord-est', 'fiche du porteur 2026-09-29 ; formation-joala/strates-et-lumiere.md', 'peu de strates basses utilisables (Dordogne)', 'Choisie pour la fonction bloque-herbe : la plus haute et la plus dense des menthes courantes (40-80 cm), elle étouffe les adventices en tapis ; indigène, supporte mieux le sec et le soleil que les autres menthes. Comme toutes les menthes elle trace par stolons : aucune ne reste vraiment en place. Théry (ch. 14) la plante en fine bande côté intérieur de la bordure, d''où elle gagne le chemin et le bord des planches — attention aux carottes et radis semés à côté. La préférer à la consoude sur les planches où l''on arrache (ch. 15). Moins traçantes mais trop faibles pour bloquer l''herbe : menthe ananas (M. suaveolens ''Variegata''), menthe de Corse (M. requienii, 3-10 cm). Système et entrée/sortie du scénario : repère général par défaut (Claude, 2026-09-30), à ajuster au film de chaque parcelle. Biomasse et taille : repère général (Claude, 2026-09-30), à caler sur la phénologie locale. Serre, bloque-herbe, bordure et déplaçable : repère (Claude, 2026-09-30, d''après le livre ch. 9 et annexes), à vérifier.') ON DUPLICATE KEY UPDATE `nom_usuel` = VALUES(`nom_usuel`), `role` = VALUES(`role`), `strates_possibles` = VALUES(`strates_possibles`), `systeme` = VALUES(`systeme`), `cycle` = VALUES(`cycle`), `hauteur_m` = VALUES(`hauteur_m`), `largeur_m` = VALUES(`largeur_m`), `strate_production` = VALUES(`strate_production`), `strate_service` = VALUES(`strate_service`), `entree_scenario` = VALUES(`entree_scenario`), `sortie_scenario` = VALUES(`sortie_scenario`), `espacement_retenu_m` = VALUES(`espacement_retenu_m`), `plants_par_ml` = VALUES(`plants_par_ml`), `periode_repiquage` = VALUES(`periode_repiquage`), `periode_recolte` = VALUES(`periode_recolte`), `biomasse` = VALUES(`biomasse`), `conduite_taille` = VALUES(`conduite_taille`), `periode_taille` = VALUES(`periode_taille`), `type_plant` = VALUES(`type_plant`), `origine` = VALUES(`origine`), `bloque_herbe` = VALUES(`bloque_herbe`), `orientation_bordure` = VALUES(`orientation_bordure`), `source` = VALUES(`source`), `statut_local` = VALUES(`statut_local`), `notes` = VALUES(`notes`);
INSERT INTO espece (`site_id`, `nom_scientifique`, `variete`, `nom_usuel`, `role`, `strates_possibles`, `systeme`, `cycle`, `temperature_sol_semis_c`, `hauteur_m`, `largeur_m`, `strate_production`, `strate_service`, `delai_germination_j`, `entree_scenario`, `sortie_scenario`, `espacement_retenu_m`, `plants_par_ml`, `periode_semis`, `periode_repiquage`, `periode_recolte`, `biomasse`, `conduite_taille`, `periode_taille`, `type_plant`, `origine`, `bloque_herbe`, `orientation_bordure`, `deplacable`, `source`, `statut_local`, `notes`) VALUES (0, 'Melissa officinalis', '', 'Mélisse', 'production|nectar|pollen|refuge|biomasse', 'basse', 'accumulation', 'vivace', 12, 0.7, 0.7, 'basse', 'basse', 14, 'placenta1', 'sec1', 0.4, 2.5, 'mi mars', 'mi mai', 'debut juin', '++', 'fauche', 'fauche à chaque début de floraison, plusieurs coupes par saison', 'godet sous abri, ou éclat de touffe', 'mixte', 1, 'nord-est', 1, 'ch11-construire-un-scenario-planter-un-film.md; strates-et-lumiere.md; calendrier-et-taille-hivernale.md', 'bordure vivante — jusqu''à trois-quatre coupes annuelles rapp', 'Graines fines, semer en surface sans couvrir. Supporte la mi-ombre : bande intérieure des bordures (Théry ch. 14). 2 à 3 coupes par an avant floraison. Se ressème abondamment. Très mellifère. Système et entrée/sortie du scénario : repère général par défaut (Claude, 2026-09-30), à ajuster au film de chaque parcelle. Biomasse et taille : repère général (Claude, 2026-09-30), à caler sur la phénologie locale. Serre, bloque-herbe, bordure et déplaçable : repère (Claude, 2026-09-30, d''après le livre ch. 9 et annexes), à vérifier.') ON DUPLICATE KEY UPDATE `nom_usuel` = VALUES(`nom_usuel`), `role` = VALUES(`role`), `strates_possibles` = VALUES(`strates_possibles`), `systeme` = VALUES(`systeme`), `cycle` = VALUES(`cycle`), `temperature_sol_semis_c` = VALUES(`temperature_sol_semis_c`), `hauteur_m` = VALUES(`hauteur_m`), `largeur_m` = VALUES(`largeur_m`), `strate_production` = VALUES(`strate_production`), `strate_service` = VALUES(`strate_service`), `delai_germination_j` = VALUES(`delai_germination_j`), `entree_scenario` = VALUES(`entree_scenario`), `sortie_scenario` = VALUES(`sortie_scenario`), `espacement_retenu_m` = VALUES(`espacement_retenu_m`), `plants_par_ml` = VALUES(`plants_par_ml`), `periode_semis` = VALUES(`periode_semis`), `periode_repiquage` = VALUES(`periode_repiquage`), `periode_recolte` = VALUES(`periode_recolte`), `biomasse` = VALUES(`biomasse`), `conduite_taille` = VALUES(`conduite_taille`), `periode_taille` = VALUES(`periode_taille`), `type_plant` = VALUES(`type_plant`), `origine` = VALUES(`origine`), `bloque_herbe` = VALUES(`bloque_herbe`), `orientation_bordure` = VALUES(`orientation_bordure`), `deplacable` = VALUES(`deplacable`), `source` = VALUES(`source`), `statut_local` = VALUES(`statut_local`), `notes` = VALUES(`notes`);
INSERT INTO espece (`site_id`, `nom_scientifique`, `variete`, `nom_usuel`, `role`, `strates_possibles`, `systeme`, `cycle`, `hauteur_m`, `largeur_m`, `entree_scenario`, `sortie_scenario`, `periode_repiquage`, `periode_recolte`, `biomasse`, `conduite_taille`, `periode_taille`, `type_plant`, `origine`, `source`, `statut_local`, `notes`) VALUES (0, 'Morus alba', '', 'Mûrier blanc', 'production', 'haute', 'abondance', 'ligneuse', 12, 10, 'placenta3', 'climax', 'fin novembre', 'mi juin', '+++', 'trogne', 'en repos végétatif, hors gel, avant le gonflement des bourgeons', 'plant racines nues, ou bouture', 'mixte', 'ch11-construire-un-scenario-planter-un-film.md, étude de cas « Les eucalyptus »', 'peut vivre jusqu''à un siècle et demi selon le chapitre', 'Hauteur et largeur : repères généraux de taille adulte libre (Claude, 2026-09-30), à vérifier. Système et entrée/sortie du scénario : repère général par défaut (Claude, 2026-09-30), à ajuster au film de chaque parcelle. Biomasse et taille : repère général (Claude, 2026-09-30), à caler sur la phénologie locale. Calendrier (repère Haute-Vienne, Claude, 2026-09-30) : mûres de juin à juillet. Type de plant et origine : repère général (Claude, 2026-09-30), à vérifier.') ON DUPLICATE KEY UPDATE `nom_usuel` = VALUES(`nom_usuel`), `role` = VALUES(`role`), `strates_possibles` = VALUES(`strates_possibles`), `systeme` = VALUES(`systeme`), `cycle` = VALUES(`cycle`), `hauteur_m` = VALUES(`hauteur_m`), `largeur_m` = VALUES(`largeur_m`), `entree_scenario` = VALUES(`entree_scenario`), `sortie_scenario` = VALUES(`sortie_scenario`), `periode_repiquage` = VALUES(`periode_repiquage`), `periode_recolte` = VALUES(`periode_recolte`), `biomasse` = VALUES(`biomasse`), `conduite_taille` = VALUES(`conduite_taille`), `periode_taille` = VALUES(`periode_taille`), `type_plant` = VALUES(`type_plant`), `origine` = VALUES(`origine`), `source` = VALUES(`source`), `statut_local` = VALUES(`statut_local`), `notes` = VALUES(`notes`);
INSERT INTO espece (`site_id`, `nom_scientifique`, `variete`, `nom_usuel`, `role`, `strates_possibles`, `systeme`, `cycle`, `hauteur_m`, `largeur_m`, `entree_scenario`, `sortie_scenario`, `espacement_retenu_m`, `plants_par_ml`, `periode_repiquage`, `periode_recolte`, `biomasse`, `conduite_taille`, `periode_taille`, `type_plant`, `origine`, `orientation_bordure`, `source`, `statut_local`, `notes`) VALUES (0, 'Rubus fruticosus', '', 'Mûrier sans épines', 'production|biomasse', 'haute|moyenne', 'accumulation', 'ligneuse', 2, 3, 'placenta3', 'sec2', 4, 4, 'fin novembre', 'fin juillet', '++', 'basitone', 'tiges ayant fructifié coupées à la base après récolte', 'bouture, marcotte ou plant', 'mixte', 'nord-est', 'fiche du porteur 2026-09-29 ; livre-bienvenue-en-syntropie ch. 14 § 4.4, plan p. 121', 'palissé sur les sureaux plantés chaque mètre, face nord ou e', 'Mûre à ronce sans épines (cultivars ''Thornless Evergreen'', ''Loch Ness'', ''Black Satin''…), pas le mûrier arbre (Morus). Bords nord et est : trois pieds entre deux sureaux plantés chaque mètre, palissés dessus (Théry ch. 14). Taille de formation aérée pour que les mûres mûrissent, une partie des tiges prélevée pour la biomasse. Récolte de fin juillet à septembre. Se marcotte seul par le bout des tiges. Strates possibles : repère général selon le besoin en lumière (Claude, 2026-09-30), à vérifier. Système et entrée/sortie du scénario : repère général par défaut (Claude, 2026-09-30), à ajuster au film de chaque parcelle. Biomasse et taille : repère général (Claude, 2026-09-30), à caler sur la phénologie locale. Serre, bloque-herbe, bordure et déplaçable : repère (Claude, 2026-09-30, d''après le livre ch. 9 et annexes), à vérifier.') ON DUPLICATE KEY UPDATE `nom_usuel` = VALUES(`nom_usuel`), `role` = VALUES(`role`), `strates_possibles` = VALUES(`strates_possibles`), `systeme` = VALUES(`systeme`), `cycle` = VALUES(`cycle`), `hauteur_m` = VALUES(`hauteur_m`), `largeur_m` = VALUES(`largeur_m`), `entree_scenario` = VALUES(`entree_scenario`), `sortie_scenario` = VALUES(`sortie_scenario`), `espacement_retenu_m` = VALUES(`espacement_retenu_m`), `plants_par_ml` = VALUES(`plants_par_ml`), `periode_repiquage` = VALUES(`periode_repiquage`), `periode_recolte` = VALUES(`periode_recolte`), `biomasse` = VALUES(`biomasse`), `conduite_taille` = VALUES(`conduite_taille`), `periode_taille` = VALUES(`periode_taille`), `type_plant` = VALUES(`type_plant`), `origine` = VALUES(`origine`), `orientation_bordure` = VALUES(`orientation_bordure`), `source` = VALUES(`source`), `statut_local` = VALUES(`statut_local`), `notes` = VALUES(`notes`);
