INSERT INTO espece (`site_id`, `nom_scientifique`, `variete`, `nom_usuel`, `role`, `strates_possibles`, `systeme`, `cycle`, `temperature_sol_semis_c`, `hauteur_m`, `largeur_m`, `strate_production`, `strate_service`, `delai_germination_j`, `entree_scenario`, `sortie_scenario`, `espacement_retenu_m`, `plants_par_ml`, `periode_semis`, `periode_repiquage`, `biomasse`, `conduite_taille`, `periode_taille`, `type_plant`, `origine`, `bloque_herbe`, `orientation_bordure`, `deplacable`, `source`, `statut_local`, `notes`) VALUES (0, 'Salvia rosmarinus', '', 'Romarin', 'production|nectar|pollen|refuge|bloque_herbe', 'emergente', 'colonisation', 'ligneuse', 15, 1.2, 2, 'emergente', 'emergente', 21, 'placenta3', 'sec1', 0.8, 1.25, 'mi mars', 'mi mai', '+', 'eventail', 'après floraison, sans couper dans le vieux bois', 'bouture, ou godet sous abri', 'mixte', 1, 'les deux', 1, 'fiche du porteur 2026-09-29 ; livre-bienvenue-en-syntropie ch. 03 § 4 ; ch. 14 § 4.2, plan p. 117', 'bande extérieure, face sud ou ouest — espacement indicatif ;', 'Synonyme : Rosmarinus officinalis. Bande extérieure des bords sud et ouest (Théry ch. 14, qui l''espace à 40 cm). Récolte des feuilles toute l''année. Floraison de fin d''hiver précieuse pour les pollinisateurs précoces. Semis lent et peu fiable, préférer la bouture. Sol drainé, craint le froid humide. Système et entrée/sortie du scénario : repère général par défaut (Claude, 2026-09-30), à ajuster au film de chaque parcelle. Biomasse et taille : repère général (Claude, 2026-09-30), à caler sur la phénologie locale. Serre, bloque-herbe, bordure et déplaçable : repère (Claude, 2026-09-30, d''après le livre ch. 9 et annexes), à vérifier.') ON DUPLICATE KEY UPDATE `nom_usuel` = VALUES(`nom_usuel`), `role` = VALUES(`role`), `strates_possibles` = VALUES(`strates_possibles`), `systeme` = VALUES(`systeme`), `cycle` = VALUES(`cycle`), `temperature_sol_semis_c` = VALUES(`temperature_sol_semis_c`), `hauteur_m` = VALUES(`hauteur_m`), `largeur_m` = VALUES(`largeur_m`), `strate_production` = VALUES(`strate_production`), `strate_service` = VALUES(`strate_service`), `delai_germination_j` = VALUES(`delai_germination_j`), `entree_scenario` = VALUES(`entree_scenario`), `sortie_scenario` = VALUES(`sortie_scenario`), `espacement_retenu_m` = VALUES(`espacement_retenu_m`), `plants_par_ml` = VALUES(`plants_par_ml`), `periode_semis` = VALUES(`periode_semis`), `periode_repiquage` = VALUES(`periode_repiquage`), `biomasse` = VALUES(`biomasse`), `conduite_taille` = VALUES(`conduite_taille`), `periode_taille` = VALUES(`periode_taille`), `type_plant` = VALUES(`type_plant`), `origine` = VALUES(`origine`), `bloque_herbe` = VALUES(`bloque_herbe`), `orientation_bordure` = VALUES(`orientation_bordure`), `deplacable` = VALUES(`deplacable`), `source` = VALUES(`source`), `statut_local` = VALUES(`statut_local`), `notes` = VALUES(`notes`);
