enario`), `sortie_scenario` = VALUES(`sortie_scenario`), `espacement_retenu_m` = VALUES(`espacement_retenu_m`), `plants_par_ml` = VALUES(`plants_par_ml`), `periode_semis` = VALUES(`periode_semis`), `periode_repiquage` = VALUES(`periode_repiquage`), `periode_recolte` = VALUES(`periode_recolte`), `biomasse` = VALUES(`biomasse`), `conduite_taille` = VALUES(`conduite_taille`), `periode_taille` = VALUES(`periode_taille`), `type_plant` = VALUES(`type_plant`), `origine` = VALUES(`origine`), `bloque_herbe` = VALUES(`bloque_herbe`), `orientation_bordure` = VALUES(`orientation_bordure`), `deplacable` = VALUES(`deplacable`), `source` = VALUES(`source`), `statut_local` = VALUES(`statut_local`), `notes` = VALUES(`notes`);
INSERT INTO espece (`site_id`, `nom_scientifique`, `variete`, `nom_usuel`, `role`, `strates_possibles`, `systeme`, `cycle`, `hauteur_m`, `largeur_m`, `entree_scenario`, `sortie_scenario`, `periode_repiquage`, `biomasse`, `rapport_cn`, `conduite_taille`, `periode_taille`, `type_plant`, `origine`, `orientation_bordure`, `source`, `statut_local`, `notes`) VALUES (0, 'Salix', '', 'Saule', 'biomasse', 'emergente|haute', 'accumulation', 'ligneuse', 10, 8, 'placenta3', 'sec2', 'fin fevrier', '++', '21', 'cepee|trogne', 'en repos végétatif, hors gel, avant le gonflement des bourgeons', 'bouture ou plançon', 'multiplication', 'nord-est', 'connaissances/formation-joala/systemes-et-abondance.md', 'repère de conception, non vérifié', 'C/N 21 : litière de feuilles de Salix alba, Danube (Ágoston-Szabó et al., 2014 ; 24 en rapport molaire). Hauteur et largeur : repères généraux de taille adulte libre (Claude, 2026-09-30), à vérifier. Strates possibles : repère général selon le besoin en lumière (Claude, 2026-09-30), à vérifier. Système et entrée/sortie du scénario : repère général par défaut (Claude, 2026-09-30), à ajuster au film de chaque parcelle. Biomasse et taille : repère général (Claude, 2026-09-30), à caler sur la phénologie locale. Calendrier (repère Haute-Vienne, Claude, 2026-09-30) : boutures en fin d''hiver. Type de plant et origine : repère général (Claude, 2026-09-30), à vérifier. Serre, bloque-herbe, bordure et déplaçable : repère (Claude, 2026-09-30, d''après le livre ch. 9 et annexes), à vérifier.') ON DUPLICATE KEY UPDATE `nom_usuel` = VALUES(`nom_usuel`), `role` = VALUES(`role`), `strates_possibles` = VALUES(`strates_possibles`), `systeme` = VALUES(`systeme`), `cycle` = VALUES(`cycle`), `hauteur_m` = VALUES(`hauteur_m`), `largeur_m` = VALUES(`largeur_m`), `entree_scenario` = VALUES(`entree_scenario`), `sortie_scenario` = VALUES(`sortie_scenario`), `periode_repiquage` = VALUES(`periode_repiquage`), `biomasse` = VALUES(`biomasse`), `rapport_cn` = VALUES(`rapport_cn`), `conduite_taille` = VALUES(`conduite_taille`), `periode_taille` = VALUES(`periode_taille`), `type_plant` = VALUES(`type_plant`), `origine` = VALUES(`origine`), `orientation_bordure` = VALUES(`orientation_bordure`), `source` = VALUES(`source`), `statut_local` = VALUES(`statut_local`), `notes` = VALUES(`notes`);
INSERT INTO espece (`site_id`, `nom_scientifique`, `variete`, `nom_usuel`, `role`, `strates_possibles`, `systeme`, `cycle`, `temperature_sol_semis_c`, `hauteur_m`, `largeur_m`, `delai_germination_j`, `entree_scenario`, `sortie_scenario`, `espacement_retenu_m`, `plants_par_ml`, `periode_semis`, `periode_repiquage`, `periode_recolte`, `biomasse`, `rapport_cn`, `conduite_taille`, `periode_taille`, `type_plant`, `origine`, `source`, `statut_local`, `notes`) VALUES (0, 'Silphium perfoliatum', '', 'Silphie', 'biomasse|nectar|pollen|racines|erosion|refuge', 'haute', 'accumulation', 'vivace', 10, 2.5, 2.5, 15, 'placenta3', 'sec1', 0.5, 2, 'mi mars', 'mi mai', 'debut septembre', '+++', '19 à 27', 'fauche', 'en vert, au plus tard quand les fleurs fanent', 'godet après stratification, ou éclat de touffe', 'achat', 'fiche du porteur 2026-09-29 ; connaissances/formation-joala/tortues-et-succession.md', 'très envahissante — occupation temporaire de l''espace centra', 'Stratifier les graines 8 semaines au froid humide avant semis. Première année en rosette seulement. Ensuite 2-3 m de haut, fauche fin août-septembre, pendant 10-15 ans. Floraison de juillet à septembre très mellifère. Les feuilles en coupe retiennent l''eau pour les insectes et les oiseaux. C/N 19 à 27 : masse verte du cultivar « Vital », Moldavie (Guțu et al., 2026). Système et entrée/sortie du scénario : repère général par défaut (Claude, 2026-09-30), à ajuster au film de chaque parcelle. Biomasse et taille : repère général (Claude, 2026-09-30), à caler sur la phénologie locale.') ON DUPLICATE KEY UPDATE `nom_usuel` = VALUES(`nom_usuel`), `role` = VALUES(`role`), `strates_possibles` = VALUES(`strates_possibles`), `systeme` = VALUES(`systeme`), `cycle` = VALUES(`cycle`), `temperature_sol_semis_c` = VALUES(`temperature_sol_semis_c`), `hauteur_m` = VALUES(`hauteur_m`), `largeur_m` = VALUES(`largeur_m`), `delai_germination_j` = VALUES(`delai_germination_j`), `entree_scenario` = VALUES(`entree_scenario`), `sortie_scenario` = VALUES(`sortie_scenario`), `espacement_retenu_m` = VALUES(`espacement_retenu_m`), `plants_par_ml` = VALUES(`plants_par_ml`), `periode_semis` = VALUES(`periode_semis`), `periode_repiquage` = VALUES(`periode_repiquage`), `periode_recolte` = VALUES(`periode_recolte`), `biomasse` = VALUES(`biomasse`), `rapport_cn` = VALUES(`rapport_cn`), `conduite_taille` = VALUES(`conduite_taille`), `periode_taille` = VALUES(`periode_taille`), `type_plant` = VALUES(`type_plant`), `origine` = VALUES(`origine`), `source` = VALUES(`source`), `statut_local` = VALUES(`statut_local`), `notes` = VALUES(`notes`);
INSERT INTO espece (`site_id`, `nom_scientifique`, `variete`, `nom_usuel`, `role`, `strates_possibles`, `systeme`, `cycle`, `temperature_sol_semis_c`, `hauteur_m`, `largeur_m`, `strate_production`, `strate_service`, `delai_germination_j`, `entree_scenario`, `sortie_scenario`, `periode_semis`, `periode_recolte`, `biomasse`, `conduite_taille`, `periode_taille`, `type_plant`, `origine`, `source`, `statut_local`, `notes`) VALUES (0, 'Calendula officinalis', '', 'Souci / calendula', 'production|refuge', 'emergente', 'accumulation', 'annuelle', 8, 0.5, 0.3, 'emergente', 'emergente', 8, 'placenta1', 'placenta2', 'debut avril', 'debut juin', '+', 'libre', 'sans objet : arrachée ou couchée au sol en fin de cycle', 'direct', 'multiplication', 'connaissances/formation-joala/strates-et-lumiere.md', 'petite taille — ne se déploie qu''en bordure ou au cœur des p', 'Hauteur et largeur : repères généraux de taille adulte libre (Claude, 2026-09-30), à vérifier. Système et entrée/sortie du scénario : repère général par défaut (Claude, 2026-09-30), à ajuster au film de chaque parcelle. Biomasse et taille : repère général (Claude, 2026-09-30), à caler sur la phénologie locale. Calendrier (repère Haute-Vienne, Claude, 2026-09-30) : fleurs de juin aux gelées. Germination (repère, Claude, 2026-09-30). Type de plant et origine : repère général (Claude, 2026-09-30), à vérifier.') ON DUPLICATE KEY UPDATE `nom_usuel` = VALUES(`nom_usuel`), `role` = VALUES(`role`), `strates_possibles` = VALUES(`strates_possibles`), `systeme` = VALUES(`systeme`), `cycle` = VALUES(`cycle`), `temperature_sol_semis_c` = VALUES(`temperature_sol_semis_c`), `hauteur_m` = VALUES(`hauteur_m`), `largeur_m` = VALUES(`largeur_m`), `strate_production` = VALUES(`strate_production`), `strate_service` = VALUES(`strate_service`), `delai_germination_j` = VALUES(`delai_germination_j`), `entree_scenario` = VALUES(`entree_scenario`), `sortie_scenario` = VALUES(`sortie_scenario`), `periode_semis` = VALUES(`periode_semis`), `periode_recolte` = VALUES(`periode_recolte`), `biomasse` = VALUES(`biomasse`), `conduite_taille` = VALUES(`conduite_taille`), `periode_taille` = VALUES(`periode_taille`), `type_plant` = VALUES(`type_plant`), `origine` = VALUES(`origine`), `source` = VALUES(`source`), `statut_local` = VALUES(`statut_local`), `notes` = VALUES(`notes`);
INSERT INTO espece (`site_id`, `nom_scientifique`, `variete`, `nom_usuel`, `role`, `strates_possibles`, `systeme`, `cycle`, `hauteur_m`, `largeur_m`, `strate_production`, `strate_service`, `entree_scenario`, `sortie_scenario`, `espacement_retenu_m`, `plants_par_ml`, `periode_repiquage`, `periode_recolte`, `biomasse`, `conduite_taille`, `periode_taille`, `type_plant`, `origine`, `serre_necessaire`, `orientation_bordure`, `deplacable`, `source`, `statut_local`, `notes`) VALUES (0, 'Sambucus nigra', '', 'Sureau', 'production|biomasse|tuteur|pollen|refuge|multiplication', 'haute|moyenne', 'accumulation', 'ligneuse', 6, 1, 'haute', 'moyenne', 'placenta3', 'sec2', 1, 1, 'fin novembre', 'fin aout', '++', 'trogne|cepee', 'en repos végétatif, hors gel, avant le gonflement des bourgeons', 'bouture de bois sec, ou plant racines nues', 'multiplication', 1, 'nord-est', 1, 'fiche du porteur 2026-09-29 ; ch11-construire-un-scenario-planter-un-film.md, étude de cas « Les eucalyptus »', 'sort du tableau vers 20-25 ans quand l''ombre du mûrier blanc', 'Planté chaque mètre sur les bords nord et est, il sert de support de palissage aux mûriers sans épines (Théry ch. 14). Bouture de bois sec en hiver, reprise très facile. Supporte le recépage : bonne biomasse. Fleurs début juin (pollen), baies fin août-septembre, à cuire (crues, légèrement toxiques). Hauteur libre 5-8 m, bien moins s''il est taillé. Sort du système vers 20-25 ans, quand l''ombre des grands arbres le rattrape (ch. 11). Système et entrée/sortie du scénario : repère général par défaut (Claude, 2026-09-30), à ajuster au film de chaque parcelle. Biomasse et taille : repère général (Claude, 2026-09-30), à caler sur la phénologie locale. Serre, bloque-herbe, bordure et déplaçable : repère (Claude, 2026-09-30, d''après le livre ch. 9 et annexes), à vérifier.') ON DUPLICATE KEY UPDATE `nom_usuel` = VALUES(`nom_usuel`), `role` = VALUES(`role`), `strates_possibles` = VALUES(`strates_possibles`), `systeme` = VALUES(`systeme`), `cycle` = VALUES(`cycle`), `hauteur_m` = VALUES(`hauteur_m`), `largeur_m` = VALUES(`largeur_m`), `strate_production` = VALUES(`strate_production`), `strate_service` = VALUES(`strate_service`), `entree_scenario` = VALUES(`entree_scenario`), `sortie_scenario` = VALUES(`sortie_scenario`), `espacement_retenu_m` = VALUES(`espacement_retenu_m`), `plants_par_ml` = VALUES(`plants_par_ml`), `periode_repiquage` = VALUES(`periode_repiquage`), `periode_recolte` = VALUES(`periode_recolte`), `biomasse` = VALUES(`biomasse`), `conduite_taille` = VALUES(`conduite_taille`), `periode_taille` = VALUES(`periode_taille`), `type_plant` = VALUES(`type_plant`), `origine` = VALUES(`origine`), `serre_necessaire` = VALUES(`serre_necessaire`), `orientation_bordure` = VALUES(`orientation_bordure`), `deplacable` = VALUES(`deplacable`), `source` = VALUES(`source`), `statut_local` = VALUES(`statut_local`), `notes` = VALUES(`notes`);
INSERT INTO espece (`site_id`, `nom_scientifique`, `variete`, `nom_usuel`, `role`, `strates_possibles`, `systeme`, `cycle`, `temperature_sol_semis_c`, `hauteur_m`, `largeur_m`, `delai_germination_j`, `entree_scenario`, `sortie_scenario`, `espacement_retenu_m`, `plants_par_ml`, `periode_semis`, `periode_repiquage`, `periode_recolte`, `biomasse`, `conduite_taille`, `periode_taille`, `type_plant`, `origine`, `bloque_herbe`, `deplacable`, `source`, `statut_local`, `notes`) VALUES (0, 'Thymus nitens', '', 'Thym luisant', 'couvre_sol|bloque_herbe|nectar|pollen|refuge|production', 'emergente', 'colonisation', 'ligneuse', 12, 0.2, 1, 14, 'placenta2', 'sec1', 0.5, 3.33, 'mi mars', 'mi mai', 'debut juin', '+', 'eventail', 'à la reprise de printemps après les gelées, puis légèrement après floraison', 'godet, bouture ou éclat', 'mixte', 1, 1, 'fiche du porteur 2026-09-29 ; remarque du porteur, 2026-09-23', 'plante « de bordure » chez les pépiniéristes, tapissant vigo', 'Thym tapissant des Cévennes. Sol pauvre, drainé, acide à neutre (contrairement aux thyms calcicoles). Supporte mieux l''humidité que le thym commun. Graines fines, semer en surface. Strates possibles : repère général selon le besoin en lumière (Claude, 2026-09-30), à vérifier. Système et entrée/sortie du scénario : repère général par défaut (Claude, 2026-09-30), à ajuster au film de chaque parcelle. Biomasse et taille : repère général (Claude, 2026-09-30), à caler sur la phénologie locale. Serre, bloque-herbe, bordure et déplaçable : repère (Claude, 2026-09-30, d''après le livre ch. 9 et annexes), à vérifier.') ON DUPLICATE KEY UPDATE `nom_usuel` = VALUES(`nom_usuel`), `role` = VALUES(`role`), `strates_possibles` = VALUES(`strates_possibles`), `systeme` = VALUES(`systeme`), `cycle` = VALUES(`cycle`), `temperature_sol_semis_c` = VALUES(`temperature_sol_semis_c`), `hauteur_m` = VALUES(`hauteur_m`), `largeur_m` = VALUES(`largeur_m`), `delai_germination_j` = VALUES(`delai_germination_j`), `entree_scenario` = VALUES(`entree_scenario`), `sortie_scenario` = VALUES(`sortie_scenario`), `espacement_retenu_m` = VALUES(`espacement_retenu_m`), `plants_par_ml` = VALUES(`plants_par_ml`), `periode_semis` = VALUES(`periode_semis`), `periode_repiquage` = VALUES(`periode_repiquage`), `periode_recolte` = VALUES(`periode_recolte`), `biomasse` = VALUES(`biomasse`), `conduite_taille` = VALUES(`conduite_taille`), `periode_taille` = VALUES(`periode_taille`), `type_plant` = VALUES(`type_plant`), `origine` = VALUES(`origine`), `bloque_herbe` = VALUES(`bloque_herbe`), `deplacable` = VALUES(`deplacable`), `source` = VALUES(`source`), `statut_local` = VALUES(`statut_local`), `notes` = VALUES(`notes`);
