de_recolte`), `biomasse` = VALUES(`biomasse`), `conduite_taille` = VALUES(`conduite_taille`), `periode_taille` = VALUES(`periode_taille`), `type_plant` = VALUES(`type_plant`), `origine` = VALUES(`origine`), `source` = VALUES(`source`), `statut_local` = VALUES(`statut_local`), `notes` = VALUES(`notes`);
INSERT INTO espece (`site_id`, `nom_scientifique`, `variete`, `nom_usuel`, `role`, `strates_possibles`, `systeme`, `cycle`, `hauteur_m`, `largeur_m`, `entree_scenario`, `sortie_scenario`, `espacement_retenu_m`, `plants_par_ml`, `periode_repiquage`, `periode_recolte`, `biomasse`, `conduite_taille`, `periode_taille`, `type_plant`, `origine`, `source`, `statut_local`, `notes`) VALUES (0, 'Helianthus tuberosus', '', 'Topinambour', 'biomasse|production|vent|nectar|pollen', 'haute', 'accumulation', 'vivace', 2.5, 0.5, 'placenta1', 'sec1', 0.4, 2.5, 'debut a fin mars', 'debut novembre', '+++', 'fauche', 'tiges couchées au sol à l''automne', 'tubercule', 'multiplication', 'fiche du porteur 2026-09-29 ; connaissances/formation-joala/tortues-et-succession.md', 'très envahissant — occupation temporaire de l''espace central', 'Très envahissant : chaque tubercule oublié repousse, à confiner. 2-3 m de haut, bon brise-vent et grosse biomasse (coucher les tiges à l''automne). Floraison tardive (septembre-octobre). Récolte de novembre à mars. Système et entrée/sortie du scénario : repère général par défaut (Claude, 2026-09-30), à ajuster au film de chaque parcelle. Biomasse et taille : repère général (Claude, 2026-09-30), à caler sur la phénologie locale.') ON DUPLICATE KEY UPDATE `nom_usuel` = VALUES(`nom_usuel`), `role` = VALUES(`role`), `strates_possibles` = VALUES(`strates_possibles`), `systeme` = VALUES(`systeme`), `cycle` = VALUES(`cycle`), `hauteur_m` = VALUES(`hauteur_m`), `largeur_m` = VALUES(`largeur_m`), `entree_scenario` = VALUES(`entree_scenario`), `sortie_scenario` = VALUES(`sortie_scenario`), `espacement_retenu_m` = VALUES(`espacement_retenu_m`), `plants_par_ml` = VALUES(`plants_par_ml`), `periode_repiquage` = VALUES(`periode_repiquage`), `periode_recolte` = VALUES(`periode_recolte`), `biomasse` = VALUES(`biomasse`), `conduite_taille` = VALUES(`conduite_taille`), `periode_taille` = VALUES(`periode_taille`), `type_plant` = VALUES(`type_plant`), `origine` = VALUES(`origine`), `source` = VALUES(`source`), `statut_local` = VALUES(`statut_local`), `notes` = VALUES(`notes`);
